type Place = { name: string; city: string; category: string; emoji: string; tone: string; description: string };
type StateData = { name: string; places: Place[] };
type UserData = { name?: string; email?: string };
type Trip = { id: string; from: string; to: string; date: string; travelers: string };
type Booking = { id: string; bookingNumber: number; place: string; state?: string; from: string; destination?: string; date?: string; travelers: number; distanceKm: number; subtotal: number; gst: number; total: number; status: string; paymentStatus: string; paymentReference: string; customerName?: string; customerEmail?: string; adminDecision?: string; bookedAt?: string };

const states = expandedStates as StateData[];
const categories = ['All', 'Nature', 'Bhakti', 'Adventure', 'Culture', 'Wildlife', 'Beaches', 'Hill Stations', 'Food'];
const PAYMENT_QR_PATH = '/resources/qr-payment.svg';
